import { HardhatUserConfig } from "hardhat/config";
import "@nomicfoundation/hardhat-toolbox";
import fs from "fs";
import path from "path";

const ACCOUNTS_COUNT = 5100; // 5000 buyers + 100 buffer

// ── Load Geth accounts (generated by scripts/gen_accounts.mjs)
function loadGethAccounts(): { privateKey: string }[] {
  const accountsPath = path.join(__dirname, "scripts", "accounts.json");
  if (!fs.existsSync(accountsPath)) {
    return [];
  }
  const { accounts } = JSON.parse(fs.readFileSync(accountsPath, "utf-8"));
  return accounts.map((a: { privateKey: string }) => ({
    privateKey: a.privateKey,
  }));
}

const gethAccounts = loadGethAccounts();

const config: HardhatUserConfig = {
  defaultNetwork: "hardhat",
  solidity: "0.8.19",
  networks: {
    hardhat: {
      // Hardhat 内置网络 & hardhat node 共用此配置
      // npx hardhat node 启动时也会读取这里的 accounts.count
      accounts: {
        count: ACCOUNTS_COUNT,
      },
    },
    localhost: {
      url: "http://127.0.0.1:8545",
      chainId: 31337,
    },
    // ── Geth --dev local node
    // Start with: ./scripts/start_geth_dev.sh
    geth_local: {
      url: "http://127.0.0.1:8545",
      chainId: 1337, // Geth --dev with genesis chainId 1337 (0x539)
      accounts: gethAccounts.length > 0
        ? gethAccounts.map((a) => a.privateKey)
        : undefined,
      // Geth --dev mines instantly; no timeout needed but raise it for safety
      timeout: 60000,
    },
  },
};

export default config;
